Method.Source:
    /// <summary>
    /// Maps entity to datasource.
    /// </summary>
    /// <param name = "_entityCtx">
    /// <c>DataEntityRuntimeContext</c>.
    /// </param>
    /// <param name = "_dataSourceCtx">
    /// <c>DataEntityDataSourceRuntimeContext</c>.
    /// </param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(InventProductSpecificOrderSettingsV3Entity, METInventItemOrderSetup):
                METInventItemOrderSetup inventItemOrderSetup =  _dataSourceCtx.getBuffer();

                if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
                {
                    inventItemOrderSetup.InventDimId  = this.metGetOrCreateInventDim().InventDimId;
                    inventItemOrderSetup.ItemId       = this.ItemNumber;
                }
                break;
        }
    }

    /// <summary>
    /// Duplicate method <c>getOrCreateInventDim</c> due to it being private.
    /// Gets InventDim.
    /// </summary>
    /// <returns>InventDim record.</returns>
    private InventDim metGetOrCreateInventDim()
    {
        InventDim inventDim = InventProductDimension::createInventDimFromTable(this);
        inventDim.InventSiteId = this.OperationalSiteId;

        this.metValidateInventoryDimensions(inventDim);

        inventDim = InventDim::findOrCreate(inventDim);

        //FieldState is set to 'Set' to avoid the framework in thinking that the mandatory field site is not set by the user.
        inventDim.fieldState(fieldNum(InventDim, InventSiteId), FieldState::Set);
        return inventDim;
    }

/// <summary>
///  Duplicate method <c>validateInventoryDimensions</c> due to it being private.
///  Validates InventDim.
/// </summary>
/// <param name = "_inventDim">InventDim.</param>
private void metValidateInventoryDimensions(InventDim _inventDim)
{
    Set allowEmptyFields = new Set(Types::Integer);
    allowEmptyFields.add(-1);
    if (!_inventDim.checkDimFieldsValid(this.ItemNumber, InventDim::findOrCreateBlank(), true, allowEmptyFields, true))
    {
        throw error("@SYS304643");
    }
}
